import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

function StatisticsViewer() {
  const [stats, setStats] = useState([]);

  useEffect(() => {
    fetch('http://localhost:3001/api/answers')
      .then(res => res.json())
      .then(data => setStats(data))
      .catch(err => console.error('Ошибка загрузки статистики:', err));
  }, []);

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-100 to-blue-100 p-6">
      <div className="max-w-4xl mx-auto bg-white rounded-2xl shadow-lg p-8">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-3xl font-bold text-indigo-600">📊 Статистика ответов</h2>
          <Link
            to="/"
            className="text-indigo-600 hover:underline text-sm"
          >
            ← Назад на главную
          </Link>
        </div>

        {stats.length === 0 ? (
          <p className="text-gray-600">Нет данных для отображения.</p>
        ) : (
          <ul className="space-y-4">
            {stats.map((item) => (
              <li
                key={item.question_id}
                className="bg-gray-50 p-4 rounded-lg shadow-sm flex justify-between items-center"
              >
                <div>
                  <p className="text-lg font-medium text-gray-800">
                    {item.question_text}
                  </p>
                  <p className="text-sm text-gray-500">
                    ID вопроса: {item.question_id}
                  </p>
                </div>
                <span className="text-xl text-indigo-700 font-semibold">
                  {item.answers_count}
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default StatisticsViewer;
